import { useState, type ReactElement } from "react";

type Filter = "all" | "unread" | "archived";

type MailboxState = {
  total: number;
  unread: number;
  filter: Filter;
};

const filters: Filter[] = ["all", "unread", "archived"];

function nextFilter(current: Filter): Filter {
  const index = filters.indexOf(current);
  return filters[(index + 1) % filters.length];
}

export function Mailbox(): ReactElement {
  const [state, setState] = useState<MailboxState>({
    total: 12,
    unread: 5,
    filter: "all",
  });
  const markRead = (): void => {
    setState((previous) => ({
      ...previous,
      unread: Math.max(0, previous.unread - 1),
    }));
  };
  const cycleFilter = (): void => {
    setState((previous) => ({ ...previous, filter: nextFilter(previous.filter) }));
  };
  return (
    <section className="mailbox">
      <p>
        {state.unread} unread of {state.total}
      </p>
      <p>Filter: {state.filter}</p>
      <button type="button" onClick={markRead}>
        Mark one read
      </button>
      <button type="button" onClick={cycleFilter}>
        Next filter
      </button>
    </section>
  );
}

