type Todo = {
  id: string;
  title: string;
  tags: string[];
};

export function withTag(todo: Todo, tag: string): Todo {
  if (todo.tags.includes(tag)) {
    return todo;
  }
  return { ...todo, tags: [...todo.tags, tag] };
}

export function withoutTag(todo: Todo, tag: string): Todo {
  return { ...todo, tags: todo.tags.filter((item) => item !== tag) };
}

