import { useMemo, useState, type ReactElement } from "react";

type Session = {
  id: string;
  wpm: number;
  seconds: number;
};

const seed: Session[] = [
  { id: "session-1", wpm: 74, seconds: 45 },
  { id: "session-2", wpm: 91, seconds: 120 },
  { id: "session-3", wpm: 88, seconds: 30 },
];

export function ThroughputBoard(): ReactElement {
  const [sessions, setSessions] = useState<Session[]>(seed);
  const bestWpm = useMemo(
    () => sessions.reduce((best, session) => Math.max(best, session.wpm), 0),
    [sessions],
  );
  const ranking = useMemo(
    () => [...sessions].sort((left, right) => right.wpm - left.wpm),
    [sessions],
  );
  const logSession = (): void => {
    setSessions((previous) => [
      ...previous,
      { id: `session-${previous.length + 1}`, wpm: 100, seconds: 60 },
    ]);
  };
  return (
    <section className="throughput">
      <p>Best: {bestWpm} wpm</p>
      <ol>
        {ranking.map((session) => (
          <li key={session.id}>
            {session.wpm} wpm in {session.seconds}s
          </li>
        ))}
      </ol>
      <button type="button" onClick={logSession}>
        Log a session
      </button>
    </section>
  );
}

