import { useEffect, useState, type ReactElement } from "react";

type CountdownProps = {
  seconds: number;
  stepMs?: number;
};

export function Countdown({
  seconds,
  stepMs = 1000,
}: CountdownProps): ReactElement {
  const [remaining, setRemaining] = useState<number>(seconds);
  useEffect(() => {
    setRemaining(seconds);
    const timer = window.setInterval(() => {
      setRemaining((previous) => Math.max(0, previous - 1));
    }, stepMs);
    return () => {
      window.clearInterval(timer);
    };
  }, [seconds, stepMs]);
  return (
    <p role="timer">
      {remaining} second(s) left
    </p>
  );
}

import {
  createContext,
  useContext,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";

type Theme = "light" | "dark";

type ThemeValue = {
  theme: Theme;
  toggle: () => void;
};

const ThemeContext = createContext<ThemeValue | null>(null);

type ThemeProviderProps = {
  children: ReactNode;
};

function ThemeProvider({ children }: ThemeProviderProps): ReactElement {
  const [theme, setTheme] = useState<Theme>("light");
  const value: ThemeValue = {
    theme,
    toggle: () => setTheme((current) => (current === "light" ? "dark" : "light")),
  };
  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
}

function ThemeReadout(): ReactElement {
  const value = useContext(ThemeContext);
  if (value === null) {
    throw new Error("ThemeReadout must be rendered inside ThemeProvider");
  }
  return (
    <div className="themed-panel">
      <p>Current theme: {value.theme}</p>
      <button type="button" onClick={value.toggle}>
        Switch theme
      </button>
    </div>
  );
}

export function ThemedPanel(): ReactElement {
  return (
    <ThemeProvider>
      <ThemeReadout />
    </ThemeProvider>
  );
}

import type { ReactElement } from "react";

type LoadState<T> =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "success"; data: T };

type Report = {
  id: string;
  label: string;
};

type LoadViewProps<T> = {
  state: LoadState<T>;
  children: (data: T) => ReactElement;
};

export function LoadView<T>({ state, children }: LoadViewProps<T>): ReactElement {
  switch (state.status) {
    case "loading":
      return <p role="status">Loading...</p>;
    case "error":
      return <p role="alert">{state.message}</p>;
    case "success":
      return children(state.data);
  }
}

export function ReportView({
  state,
}: {
  state: LoadState<Report>;
}): ReactElement {
  return (
    <LoadView state={state}>
      {(report) => <h2>{report.label}</h2>}
    </LoadView>
  );
}

import { useEffect, useState, type ReactElement } from "react";

type Profile = {
  id: string;
  name: string;
};

type ProfileState =
  | { status: "loading" }
  | { status: "error"; message: string }
  | { status: "success"; data: Profile };

type LoadProfile = (signal: AbortSignal) => Promise<Profile>;

export function useProfile(load: LoadProfile): ProfileState {
  const [state, setState] = useState<ProfileState>({ status: "loading" });
  useEffect(() => {
    const controller = new AbortController();
    let active = true;
    load(controller.signal).then(
      (data) => {
        if (active) {
          setState({ status: "success", data });
        }
      },
      (error: unknown) => {
        if (active) {
          setState({
            status: "error",
            message: error instanceof Error ? error.message : "Unknown error",
          });
        }
      },
    );
    return () => {
      active = false;
      controller.abort();
    };
  }, [load]);
  return state;
}

type ProfileCardProps = {
  load: LoadProfile;
};

export function ProfileCard({ load }: ProfileCardProps): ReactElement {
  const state = useProfile(load);
  if (state.status === "loading") {
    return <p role="status">Loading profile...</p>;
  }
  if (state.status === "error") {
    return <p role="alert">{state.message}</p>;
  }
  return (
    <h2>
      {state.data.name} ({state.data.id})
    </h2>
  );
}

